    private function do_fetch_markets($params = array()) {
        /**
         * fetches every kind of opinion market
         * categorical parents double unified "events" and are cached into $this->events side effect
         *
         * @see https://docs.opinion.trade/developer-guide/opinion-open-api/market
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {int} [$params->limit] max number of markets to collect (defaults to options.marketsPageLimit * options.maxMarketsPages, 1000)
         * @return {array[]} an array of objects representing market data
         */
        $rest = $this->omit($params, array( 'limit' ));
        $userLimit = $this->safe_integer($params, 'limit');
        $pageLimit = $this->safe_integer($this->options, 'marketsPageLimit', 20);
        $maxPages = $this->safe_integer($this->options, 'maxMarketsPages', 50);
        $flatMarkets = array();
        // seen-guard keyed by the $event handle; the events themselves go through setEvents below
        // so the cache gets the base indexing (id . handle . slug) instead of a $raw assignment
        $seenEvents = array();
        $eventsList = array();
        $page = 1;
        $fetchedRawCount = 0;
        while (true) {
            $request = array(
                'marketType' => 2, // all - both standalone binaries and categorical parents
                'limit' => $pageLimit,
                'page' => $page,
            );
            $response = Async\await($this->opinionPublicGetMarket($this->extend($request, $rest)));
            $result = $this->safe_dict($response, 'result', array());
            $rawMarkets = $this->safe_list($result, 'list', array());
            $rawMarketsLength = count($rawMarkets);
            $fetchedRawCount = $this->sum($fetchedRawCount, $rawMarketsLength);
            // categorical parents expand into several $flatMarkets entries each, so the $raw,
            // unflattened row count in 'total' must be compared against $fetchedRawCount, not
            // strlen($flatMarkets) - otherwise expansion makes the comparison meaningless
            $total = $this->safe_integer($result, 'total');
            for ($i = 0; $i < $rawMarketsLength; $i++) {
                $raw = $rawMarkets[$i];
                $marketType = $this->safe_integer($raw, 'marketType');
                if ($marketType === 1) {
                    $event = $this->parse_event($raw);
                    $childMarkets = $event['markets'];
                    $childMarketsLength = count($childMarkets);
                    for ($ci = 0; $ci < $childMarketsLength; $ci++) {
                        $flatMarkets[] = $childMarkets[$ci];
                    }
                    $eventKey = $this->safe_string($event, 'event');
                    if (($eventKey !== null) && ($eventKey !== '') && !(is_array($seenEvents) && array_key_exists($eventKey ?? '', $seenEvents))) {
                        $seenEvents[$eventKey] = true;
                        $eventsList[] = $event;
                    }
                } else {
                    $flatMarkets[] = $this->parse_opinion_market($raw);
                }
            }
            $collectedLength = count($flatMarkets);
            if (($rawMarketsLength < $pageLimit) || ($page >= $maxPages) || (($total !== null) && ($fetchedRawCount >= $total)) || (($userLimit !== null) && ($collectedLength >= $userLimit))) {
                break;
            }
            $page = $this->sum($page, 1);
        }
        $this->set_events($eventsList);
        $flatMarketsLength = count($flatMarkets);
        if (($userLimit !== null) && ($flatMarketsLength > $userLimit)) {
            return $this->array_slice($flatMarkets, 0, $userLimit);
        }
        return $flatMarkets;
    }

    public function fetch_outcome(string $outcomeSymbol): PromiseInterface {
        return Async\async(self::do_fetch_outcome(...))($outcomeSymbol);
