    private function do_fetch_outcome(string $outcomeSymbol) {
        /**
         * @ignore
         * resolves a single outcome; a bare numeric token id carries no search text for
         * the base's fetchEvents-driven resolution (opinion has no per-id lookup endpoint, unlike
         * kalshi/polymarket), so bulk-warm the outcome cache via loadOutcomes() first for id-form input
         * @param {string} $outcomeSymbol the outcome handle or token id
         * @return {array} the outcome cache
         */
        if ($this->outcome_search_query($outcomeSymbol) === null) {
            Async\await($this->load_outcomes());
            if ($this->has_outcome($outcomeSymbol)) {
                return $this->safe_outcome($outcomeSymbol);
            }
        }
        return Async\await(parent::fetch_outcome($outcomeSymbol));
    }

    public function parse_opinion_market(array $raw, ?string $eventSlug = null): array {
        /**
         * @ignore
         * converts a single $raw opinion market into one ccxt market with yes/no $outcomes
         * @param {array} $raw the $raw opinion market object
         * @param {string} [$eventSlug] the $slug of the parent event
         * @return {array} a [market structure](https://docs.ccxt.com/#/?id=market-structure)
         */
        // {
        //     "chainId" => "56",
        //     "conditionId" => "469db44df1309dac7cf9fcaa142562f3c89719d47277e095d021c1561166539a",
        //     "createdAt" => 1778750719,
        //     "cutoffAt" => 0,
        //     "isResolvableByAI" => true,
        //     "marketId" => 16565,
        //     "marketTitle" => "10–15s",
        //     "noLabel" => "No",
        //     "noTokenId" => "48641131337815600205538397357674754469573755318952418769815647071528778171134",
        //     "questionId" => "63907f471c045499f69b5ea157bdea1942f9d53b6e5e767ae69f4d148aeeefae",
        //     "quoteToken" => "0x55d398326f99059fF775485246999027B3197955",
        //     "rebate" => array(
        //         "maker" => 0.5
        //     ),
        //     "resolvedAt" => 1779342061,
        //     "resultTokenId" => "107063188116504514729209026208703521982564071792212276771696073817845504321279",
        //     "rules" => "",
        //     "slug" => "how-long-will-trump-and-xi-shake-hands-when-they-meet-10-15s",
        //     "status" => 4,
        //     "statusEnum" => "Resolved",
        //     "volume" => "50",
        //     "yesLabel" => "Yes",
        //     "yesTokenId" => "107063188116504514729209026208703521982564071792212276771696073817845504321279"
        // }
        $marketId = $this->safe_string($raw, 'marketId');
        $slug = $this->safe_string($raw, 'slug');
        $effectiveEventSlug = $eventSlug;
        if (($eventSlug !== null) && ($slug !== null) && (mb_strpos($slug, $eventSlug) === 0)) {
            $effectiveEventSlug = null;
        }
        $marketSymbol = $this->slug_to_market_symbol($effectiveEventSlug, $slug);
        $statusEnum = $this->safe_string($raw, 'statusEnum');
        $active = ($statusEnum === 'Activated');
        $resolved = ($statusEnum === 'Resolved');
        $resultTokenId = $this->safe_string($raw, 'resultTokenId');
        $hasResult = $resolved && ($resultTokenId !== null) && ($resultTokenId !== '');
        $outcomeLabels = array(
            $this->safe_string($raw, 'yesLabel', 'YES'),
            $this->safe_string($raw, 'noLabel', 'NO'),
        );
        $outcomeTokenIds = array(
            $this->safe_string($raw, 'yesTokenId'),
            $this->safe_string($raw, 'noTokenId'),
        );
        $outcomes = array();
        $resolvedOutcome = null;
        for ($i = 0; $i < count($outcomeLabels); $i++) {
            $label = $outcomeLabels[$i];
            $tokenId = $outcomeTokenIds[$i];
            $outcomeHandle = $this->slug_to_outcome_symbol($effectiveEventSlug, $slug, $label);
            $winner = null;
            $settleFraction = null;
            if ($hasResult) {
                $winner = ($tokenId === $resultTokenId);
                $settleFraction = $winner ? 1 : 0;
                if ($winner) {
                    $resolvedOutcome = $outcomeHandle;
                }
            }
            $outcomes[] = array(
                'id' => $tokenId,
                'outcomeId' => $tokenId,
                'outcome' => $outcomeHandle,
                'market' => $marketSymbol,
                'label' => $label,
                'active' => $active,
                'winner' => $winner,
                'settleFraction' => $settleFraction,
                'info' => $raw,
            );
        }
        $marketResolvedOutcome = $resolvedOutcome;
        // the venue sends cutoffAt 0 for markets without a scheduled cutoff - map it to
        // null instead of the epoch, same for the event-level end date
        $expiryTimestamp = null;
        if ($this->safe_integer($raw, 'cutoffAt', 0) !== 0) {
            $expiryTimestamp = $this->safe_timestamp($raw, 'cutoffAt');
        }
        $created = $this->safe_timestamp($raw, 'createdAt');
        return array(
            'id' => $marketId,
            'market' => $marketSymbol,
            'base' => 'USDT',
            'quote' => 'USDT',
            'settle' => null,
            'baseId' => $marketId,
            'quoteId' => 'USDT',
            'settleId' => null,
            'type' => 'prediction',
            'marketType' => 'binary',
            'executionModel' => 'clob',
            'spot' => false,
            'margin' => false,
            'swap' => false,
            'future' => false,
            'option' => false,
            'prediction' => true,
            'active' => $active,
            'resolved' => $resolved,
            'resolvedOutcome' => $marketResolvedOutcome,
            'contract' => false,
            'linear' => null,
            'inverse' => null,
            'contractSize' => null,
            'expiry' => $expiryTimestamp,
            'expiryDatetime' => $this->iso8601($expiryTimestamp),
            'strike' => null,
            'optionType' => null,
            'taker' => $this->fees['trading']['taker'],
            'maker' => $this->fees['trading']['maker'],
            'percentage' => true,
            'tierBased' => false,
            'feeSide' => 'get',
            'precision' => array(
                'amount' => null,
                'price' => null,
            ),
            'limits' => array(
                'leverage' => array( 'min' => 1, 'max' => 1 ),
                'amount' => array( 'min' => null, 'max' => null ),
                'price' => array( 'min' => 0, 'max' => 1 ),
                'cost' => array( 'min' => null, 'max' => null ),
            ),
            'outcomes' => $outcomes,
            'info' => $raw,
            'created' => $created,
        );
    }

    public function fetch_events($params = array()): PromiseInterface {
        return Async\async(self::do_fetch_events(...))($params);
    }

    private function do_fetch_events($params = array()) {
        /**
         * fetches Opinion's categorical markets - scope required via query/queries/tags/eventId/slug/labelId
         *
         * @see https://docs.opinion.trade/developer-guide/opinion-open-api/market
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {int} [$params->labelId] filter by opinion category label id
         * @param {int} [$params->limit] max number of events to fetch (paginated server-side; defaults to options.maxFetchEventsResults, 100)
         * @return {array[]} an array of $event structures
         */
        $this->require_event_query($params);
        $queries = $this->parse_search_queries($params);
        $eventId = $this->safe_string($params, 'eventId');
        $slug = $this->safe_string($params, 'slug');
        if (($eventId !== null) || ($slug !== null)) {
            $singleRest = $this->omit($params, array( 'eventId', 'slug', 'query', 'queries', 'tags', 'status', 'sort', 'searchIn', 'limit' ));
            $singleResponse = null;
            if ($slug !== null) {
                $singleResponse = Async\await($this->opinionPublicGetMarketSlugSlug($this->extend(array( 'slug' => $slug ), $singleRest)));
            } else {
                $singleResponse = Async\await($this->opinionPublicGetMarketCategoricalMarketId($this->extend(array( 'marketId' => $eventId ), $singleRest)));
            }
            $singleResult = $this->safe_dict($singleResponse, 'result', array());
            $singleData = $this->safe_dict($singleResult, 'data', array());
            $single = $this->parse_event($singleData);
            $this->index_event_outcomes($single);
            return $this->apply_event_fetch_params(array( $single ), $params, $queries);
        }
        $rest = $this->omit($params, array( 'query', 'queries', 'tags', 'status', 'sort', 'searchIn', 'limit' ));
        $pageLimit = $this->safe_integer($this->options, 'defaultFetchEventsLimit', 20);
        $userLimit = $this->safe_integer($params, 'limit');
        // bound how many events are actually FETCHED => the user limit when given, otherwise
        // options.maxFetchEventsResults - the scope filters keep the listing narrow, but a broad
        // label can still hold more than one $page
        $fetchCap = $this->safe_integer($this->options, 'maxFetchEventsResults', 100);
        if ($userLimit !== null) {
            $fetchCap = $userLimit;
        }
        $maxPages = $this->safe_integer($this->options, 'maxEventsPages', 50);
        $rawEvents = array();
        $page = 1;
        $fetchedRawCount = 0;
        while (true) {
            $reqLimit = $pageLimit;
            $remaining = $fetchCap - $fetchedRawCount;
            if ($remaining < $reqLimit) {
                $reqLimit = $remaining;
            }
            if ($reqLimit <= 0) {
                break;
            }
            $request = array(
                'marketType' => 1, // categorical only - these are the ones with childMarkets, our unified "event"
                'limit' => $reqLimit,
                'page' => $page,
            );
            $response = Async\await($this->opinionPublicGetMarket($this->extend($request, $rest)));
            $result = $this->safe_dict($response, 'result', array());
            $pageEvents = $this->safe_list($result, 'list', array());
            $pageEventsLength = count($pageEvents);
            $fetchedRawCount = $this->sum($fetchedRawCount, $pageEventsLength);
            for ($i = 0; $i < $pageEventsLength; $i++) {
                $rawEvents[] = $pageEvents[$i];
            }
            $total = $this->safe_integer($result, 'total');
            if (($pageEventsLength < $reqLimit) || ($page >= $maxPages) || (($total !== null) && ($fetchedRawCount >= $total)) || ($fetchedRawCount >= $fetchCap)) {
                break;
            }
            $page = $this->sum($page, 1);
        }
        $rawEventsLength = count($rawEvents);
        $parsedEvents = array();
        if ($this->markets === null) {
            $this->markets = $this->create_safe_dictionary();
        }
        for ($i = 0; $i < $rawEventsLength; $i++) {
            $event = $this->parse_event($rawEvents[$i]);
            $parsedEvents[] = $event;
            // register the parsed markets so populateOutcomes can index their outcomes
            $eventMarkets = $this->safe_list($event, 'markets', array());
            $eventMarketsLength = count($eventMarkets);
            for ($mi = 0; $mi < $eventMarketsLength; $mi++) {
                $m = $eventMarkets[$mi];
                $this->markets[$m['market']] = $m;
            }
        }
        $this->populate_outcomes();
        return $this->apply_event_fetch_params($parsedEvents, $params, $queries);
    }

    public function fetch_event(string $id, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_event(...))($id, $params);
    }

    private function do_fetch_event(string $id, $params = array()) {
        /**
         * fetches a single prediction-market $event by its market $id, or slug
         *
         * @see https://docs.opinion.trade/developer-guide/opinion-open-api/market
         *
         * @param {string} $id the numeric marketId, or the market slug
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a [prediction $event structure](https://docs.ccxt.com/#/?$id=prediction-$event-structure)
         */
        $isSlug = (mb_strpos($id, '-') !== false);
        $response = null;
        if ($isSlug) {
            $response = Async\await($this->opinionPublicGetMarketSlugSlug($this->extend(array( 'slug' => $id ), $params)));
        } else {
            $response = Async\await($this->opinionPublicGetMarketCategoricalMarketId($this->extend(array( 'marketId' => $id ), $params)));
        }
        $result = $this->safe_dict($response, 'result', array());
        $data = $this->safe_dict($result, 'data', array());
        $event = $this->parse_event($data);
        $this->index_event_outcomes($event);
        return $event;
    }

