    public function fetch_ticker(string $outcome, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_ticker(...))($outcome, $params);
    }

    private function do_fetch_ticker(string $outcome, $params = array()) {
        /**
         * fetches the latest trade price and top of book for a single $outcome token
         *
         * @see https://docs.opinion.trade/developer-guide/opinion-open-api/token
         *
         * @param {string} $outcome unified $outcome or $outcome token id
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a [prediction ticker structure](https://docs.ccxt.com/#/?id=prediction-ticker-structure)
         */
        $outcomeObj = Async\await($this->load_outcome($outcome));
        $tokenId = $outcomeObj['outcomeId'];
        $promises = array(
            $this->opinionPublicGetTokenLatestPrice($this->extend(array( 'token_id' => $tokenId ), $params)),
            $this->opinionPublicGetTokenOrderbook($this->extend(array( 'token_id' => $tokenId ), $params)),
        );
        list($priceResponse, $bookResponse) = Async\await(Promise\all($promises));
        $response = array( 'price' => $priceResponse, 'book' => $bookResponse );
        return $this->parse_prediction_ticker($response, $outcomeObj);
    }

    public function parse_prediction_ticker(array $ticker, ?array $market = null): array {
        /**
         * @ignore
         * parses a raw opinion latest-price . orderbook pair into a unified $ticker object
         * @param {array} $ticker a array( price, book ) dict of the two raw responses
         * @param {array} [$market] the outcome object the $ticker belongs to
         * @return {array} a [prediction $ticker structure](https://docs.ccxt.com/#/?id=prediction-$ticker-structure)
         */
        //
        //     {
        //         "price" => array(
        //             "errmsg" => "",
        //             "errno" => 0,
        //             "result" => array( "price" => "0.002", "side" => "buy-limit", "size" => "205.03", "timestamp" => 1766844546000, "tokenId" => "..." )
        //         ),
        //         "book" => {
        //             "errmsg" => "",
        //             "errno" => 0,
        //             "result" => array( "asks" => array( array( "price" => "0.999", "size" => "5500" ) ), "bids" => array(), "market" => "...", "timestamp" => ..., "tokenId" => "..." )
        //         }
        //     }
        //
        $marketAny = $market;
        $priceResponse = $this->safe_dict($ticker, 'price', array());
        $priceResult = $this->safe_dict($priceResponse, 'result', array());
        $bookResponse = $this->safe_dict($ticker, 'book', array());
        $bookResult = $this->safe_dict($bookResponse, 'result', array());
        $bids = $this->safe_list($bookResult, 'bids', array());
        $asks = $this->safe_list($bookResult, 'asks', array());
        $bestBid = $this->safe_dict($bids, 0, array());
        $bestAsk = $this->safe_dict($asks, 0, array());
        $last = $this->safe_number($priceResult, 'price');
        $timestamp = $this->safe_integer($priceResult, 'timestamp', $this->milliseconds());
        return $this->safe_prediction_ticker(array(
            'outcome' => $this->safe_string($marketAny, 'outcome'),
            'outcomeId' => $this->safe_string_2($marketAny, 'outcomeId', 'id'),
            'label' => $this->safe_string($marketAny, 'label'),
            'market' => $this->safe_string_2($marketAny, 'market', 'outcome'),
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'high' => null,
            'low' => null,
            'bid' => $this->safe_number($bestBid, 'price'),
            'bidVolume' => $this->safe_number($bestBid, 'size'),
            'ask' => $this->safe_number($bestAsk, 'price'),
            'askVolume' => $this->safe_number($bestAsk, 'size'),
            'open' => null,
            'close' => $last,
            'last' => $last,
            'change' => null,
            'percentage' => null,
            'average' => null,
            'baseVolume' => null,
            'quoteVolume' => null,
            'info' => $ticker,
        ), $market);
    }

    public function fetch_tickers(?array $outcomes = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_tickers(...))($outcomes, $params);
    }

    private function do_fetch_tickers(?array $outcomes = null, $params = array()) {
        /**
         * fetches tickers for multiple outcome tokens - opinion has no all-tickers endpoint, each token needs its own latest-price . orderbook request
         *
         * @see https://docs.opinion.trade/developer-guide/opinion-open-api/token
         *
         * @param {string[]} $outcomes unified $outcomes or outcome token ids - required, opinion has no all-tickers endpoint
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a dictionary of [prediction $ticker structures](https://docs.ccxt.com/#/?id=prediction-$ticker-structure) indexed by outcome
         */
        if ($outcomes === null) {
            throw new ArgumentsRequired($this->id . ' fetchTickers() requires an $outcomes argument — the venue has no all-tickers endpoint; pass the outcome handles or token ids to fetch (discover them via fetchEvents ())');
        }
        Async\await($this->load_outcomes($outcomes));
        $outcomesLength = count($outcomes);
        $promises = array();
        for ($i = 0; $i < $outcomesLength; $i++) {
            $outcomeObj = $this->outcome($outcomes[$i]);
            $tokenId = $outcomeObj['outcomeId'];
            $promises[] = $this->opinionPublicGetTokenLatestPrice($this->extend(array( 'token_id' => $tokenId ), $params));
            $promises[] = $this->opinionPublicGetTokenOrderbook($this->extend(array( 'token_id' => $tokenId ), $params));
        }
        $responses = Async\await(Promise\all($promises));
        $result = array();
        for ($i = 0; $i < $outcomesLength; $i++) {
            $outcomeObj = $this->outcome($outcomes[$i]);
            $priceIndex = $i * 2;
            $priceResponse = $responses[$priceIndex];
            $bookResponse = $responses[$this->sum($priceIndex, 1)];
            $response = array( 'price' => $priceResponse, 'book' => $bookResponse );
            $ticker = $this->parse_prediction_ticker($response, $outcomeObj);
            $symbolKey = $this->safe_string($ticker, 'outcome');
            if ($symbolKey !== null) {
                $result[$symbolKey] = $ticker;
            }
        }
        return $result;
    }

    public function fetch_order_book(?string $outcome, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_order_book(...))($outcome, $limit, $params);
    }

    private function do_fetch_order_book(?string $outcome, ?int $limit = null, $params = array()) {
        /**
         * fetches the order book for a single $outcome token
         *
         * @see https://docs.opinion.trade/developer-guide/opinion-open-api/token
         *
         * @param {string} $outcome unified $outcome or $outcome token id
         * @param {int} [$limit] not used by opinion fetchOrderBook
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a [prediction order book structure](https://docs.ccxt.com/#/?id=prediction-order-book-structure)
         */
        $outcomeObj = Async\await($this->load_outcome($outcome));
        $tokenId = $outcomeObj['outcomeId'];
        $request = array(
            'token_id' => $tokenId,
        );
        $response = Async\await($this->opinionPublicGetTokenOrderbook($this->extend($request, $params)));
        //
        //     {
        //         "errmsg" => "",
        //         "errno" => 0,
        //         "result" => {
        //             "asks" => array(
        //                 array( "price" => "0.999", "size" => "5500" )
        //             ),
        //             "bids" => array(),
        //             "market" => "ff7d2d935d0cce2922ea05a363e5a87439e1f8f86f01dacf7238d4c4cc542f6c",
        //             "timestamp" => 1785488076901,
        //             "tokenId" => "56915117085756475550546730127709511264652860289185956800398231821503615918119"
        //         }
        //     }
        //
        $result = $this->safe_dict($response, 'result', array());
        $timestamp = $this->safe_integer($result, 'timestamp');
        $orderbook = $this->parse_order_book($result, $this->safe_outcome_symbol($outcome, $outcomeObj), $timestamp, 'bids', 'asks', 'price', 'size');
        return $this->safe_prediction_order_book($orderbook, $outcomeObj);
    }

    public function fetch_ohlcv(string $outcome, $timeframe = '1d', ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_ohlcv(...))($outcome, $timeframe, $since, $limit, $params);
    }

    private function do_fetch_ohlcv(string $outcome, $timeframe = '1d', ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches historical candlestick data for an $outcome token
         *
         * @see https://docs.opinion.trade/developer-guide/opinion-open-api/token
         *
         * @param {string} $outcome unified $outcome or $outcome token id
         * @param {string} $timeframe the length of time each candle represents - only '1h' and '1d' are supported live
         * @param {int} [$since] $timestamp in ms of the earliest candle to fetch
         * @param {int} [$limit] the maximum number of $candles to return
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {int[][]} a list of $candles ordered, open, high, low, close, volume
         */
        if (!(is_array($this->timeframes) && array_key_exists($timeframe ?? '', $this->timeframes))) {
            $supportedKeys = is_array($this->timeframes) ? array_keys($this->timeframes) : array();
            throw new BadRequest($this->id . ' fetchOHLCV() unsupported $timeframe ' . $timeframe . ', supported timeframes are ' . implode(', ', $supportedKeys));
        }
        $outcomeObj = Async\await($this->load_outcome($outcome));
        $tokenId = $outcomeObj['outcomeId'];
        $interval = $this->safe_string($this->timeframes, $timeframe);
        $response = Async\await($this->opinionPublicGetTokenPriceHistory($this->extend(array(
            'token_id' => $tokenId,
            'interval' => $interval,
        ), $params)));
        //
        //     {
        //         "errmsg" => "",
        //         "errno" => 0,
        //         "result" => {
        //             "history" => array(
        //                 array( "p" => "0.001", "t" => 1785495600 )
        //             )
        //         }
        //     }
        //
        $result = $this->safe_dict($response, 'result', array());
        $history = $this->safe_list($result, 'history', array());
        $candles = array();
        $historyLength = count($history);
        for ($i = 0; $i < $historyLength; $i++) {
            $point = $history[$i];
            $price = $this->safe_number($point, 'p');
            $timestamp = $this->safe_timestamp($point, 't');
            if (($price !== null) && ($timestamp !== null)) {
                $candles[] = array( $timestamp, $price, $price, $price, $price, null );
            }
        }
        $sorted = $this->sort_by($candles, 0);
        return $this->filter_by_since_limit($sorted, $since, $limit, 0);
    }

    public function parse_ohlcv(mixed $ohlcv, ?array $market = null): array {
        /**
         * parses a single opinion $price-history point into a unified OHLCV candle
         * @param {array} $ohlcv the raw array( p, t ) point
         * @param {array} [$market] the outcome object the candle belongs to
         * @return {int[]} a candle ordered, open, high, low, close, volume
         */
        // Unused => fetchOHLCV maps array( p, t ) points directly.
        //
        //     array( "p" => "0.001", "t" => 1785495600 )
        //
        $price = $this->safe_number($ohlcv, 'p');
        return array( $this->safe_timestamp($ohlcv, 't'), $price, $price, $price, $price, null );
    }

    public function load_quote_token(?string $quoteTokenAddress): PromiseInterface {
        return Async\async(self::do_load_quote_token(...))($quoteTokenAddress);
    }

    private function do_load_quote_token(?string $quoteTokenAddress) {
        /**
         * @ignore
         * fetches and caches quote-token metadata needed to sign orders
         * @param {string} $quoteTokenAddress the on-chain quote-token contract $address, read from a 'quoteToken' field
         * @return {array} the matching quote-token $entry
         */
        if ($quoteTokenAddress === null) {
            throw new ArgumentsRequired($this->id . ' loadQuoteToken() requires a quoteTokenAddress');
        }
        $cacheKey = strtolower($quoteTokenAddress);
        $cached = $this->safe_dict($this->options, 'quoteTokens', array());
        $existing = $this->safe_dict($cached, $cacheKey);
        if ($existing !== null) {
            return $existing;
        }
        $response = Async\await($this->opinionPublicGetQuoteToken(array()));
        $result = $this->safe_dict($response, 'result', array());
        $list = $this->safe_list($result, 'list', array());
        $listLength = count($list);
        $quoteTokens = array();
        for ($i = 0; $i < $listLength; $i++) {
            $entry = $list[$i];
            $address = $this->safe_string_lower($entry, 'quoteTokenAddress');
            if ($address !== null) {
                $quoteTokens[$address] = $entry;
            }
        }
        $this->options['quoteTokens'] = $quoteTokens;
        $quoteToken = $this->safe_dict($quoteTokens, $cacheKey);
        if ($quoteToken === null) {
            throw new ExchangeError($this->id . ' loadQuoteToken() could not find quote token ' . $quoteTokenAddress);
        }
        return $quoteToken;
    }

    public function load_multi_sign_address(): PromiseInterface {
        return Async\async(self::do_load_multi_sign_address(...))();
    }

    private function do_load_multi_sign_address() {
        /**
         * @ignore
         * fetches and caches the per-wallet multi-signature address that owns order assets
         * @return {string} the multi-sig wallet address for $this->walletAddress on chain 56, or $this->walletAddress itself if none exists yet
         */
        $cached = $this->safe_string($this->options, 'multiSignAddress');
        if ($cached !== null) {
            return $cached;
        }
        $response = Async\await($this->opinionPrivateGetUserAuth(array()));
        $result = $this->safe_dict($response, 'result', array());
        $walletUsers = $this->safe_dict($result, 'walletUsers', array());
        $multiSignAddress = $this->safe_string($walletUsers, '56', $this->walletAddress);
        $this->options['multiSignAddress'] = $multiSignAddress;
        return $multiSignAddress;
    }

    public function sign_opinion_order(array $order, string $exchangeAddress): string {
        $domain = array(
            'name' => 'OPINION CTF Exchange',
            'version' => '1',
            'chainId' => 56,
            'verifyingContract' => $exchangeAddress,
        );
        $messageTypes = array(
            'Order' => array(
                array( 'name' => 'salt', 'type' => 'uint256' ),
                array( 'name' => 'maker', 'type' => 'address' ),
                array( 'name' => 'signer', 'type' => 'address' ),
                array( 'name' => 'taker', 'type' => 'address' ),
                array( 'name' => 'tokenId', 'type' => 'uint256' ),
                array( 'name' => 'makerAmount', 'type' => 'uint256' ),
                array( 'name' => 'takerAmount', 'type' => 'uint256' ),
                array( 'name' => 'expiration', 'type' => 'uint256' ),
                array( 'name' => 'nonce', 'type' => 'uint256' ),
                array( 'name' => 'feeRateBps', 'type' => 'uint256' ),
                array( 'name' => 'side', 'type' => 'uint8' ),
                array( 'name' => 'signatureType', 'type' => 'uint8' ),
            ),
        );
        $encoded = $this->eth_encode_structured_data($domain, $messageTypes, $order);
        $sig = $this->sign_message($encoded, $this->privateKey);
        return '0x' . $this->remove0x_prefix($sig['r']) . $this->remove0x_prefix($sig['s']) . $this->int_to_base16($sig['v']);
    }

    public function opinion_order_raw_amounts(bool $isMarket, string $side, ?float $amount, ?float $price, float $decimals): array {
        $decimalsStr = '1';
        for ($i = 0; $i < $decimals; $i++) {
            $decimalsStr = $decimalsStr . '0';
        }
        $amountStr = $this->number_to_string($amount);
        if ($isMarket && ($side === 'BUY')) {
            $marketMakerAmountWei = $this->decimal_to_precision(Precise::string_mul($amountStr, $decimalsStr), TRUNCATE, 0, DECIMAL_PLACES);
            return array( 'makerAmount' => $marketMakerAmountWei, 'takerAmount' => '0' );
        }
        $priceStr = $this->decimal_to_precision($this->number_to_string($price), ROUND, 6, DECIMAL_PLACES);
        $priceParts = explode('.', $priceStr);
        $priceInt = $this->safe_string($priceParts, 0, '0');
        $priceFrac = $this->safe_string($priceParts, 1, '');
        $priceDenom = '1000000';
        $priceNum = Precise::string_add(Precise::string_mul($priceInt, $priceDenom), str_pad($priceFrac, 6, '0', STR_PAD_RIGHT));
        if ($priceNum === '0') {
            throw new InvalidOrder($this->id . ' createOrder() invalid $price ' . $priceStr);
        }
        $makerRaw = $amountStr;
        if ($side === 'BUY') {
            $makerRaw = Precise::string_mul($amountStr, $priceStr);
        }
        $makerAmountWei = $this->decimal_to_precision(Precise::string_mul($makerRaw, $decimalsStr), TRUNCATE, 0, DECIMAL_PLACES);
        if ($side === 'BUY') {
            $k = Precise::string_div($makerAmountWei, $priceNum, 0);
            $makerAmount = Precise::string_mul($k, $priceNum);
            $takerAmount = Precise::string_mul($k, $priceDenom);
        } else {
            $k = Precise::string_div($makerAmountWei, $priceDenom, 0);
            $makerAmount = Precise::string_mul($k, $priceDenom);
            $takerAmount = Precise::string_mul($k, $priceNum);
        }
        return array( 'makerAmount' => $makerAmount, 'takerAmount' => $takerAmount );
    }

    public function create_order(string $outcome, ?string $type, ?string $side, ?float $amount, ?float $price = null, $params = array()): PromiseInterface {
        return Async\async(self::do_create_order(...))($outcome, $type, $side, $amount, $price, $params);
    }

    private function do_create_order(string $outcome, ?string $type, ?string $side, ?float $amount, ?float $price = null, $params = array()) {
        /**
         * places a limit or market $order on the CLOB for the given $outcome token
         *
         * @see https://docs.opinion.trade/developer-guide/opinion-open-api/order
         *
         * @param {string} $outcome unified $outcome or $outcome token id
         * @param {string} $type 'market' or 'limit'
         * @param {string} $side 'buy' or 'sell'
         * @param {float} $amount for limit orders, the number of $outcome shares to trade; for market orders, the quote (USDT) to spend on a BUY or the shares to sell on a SELL
         * @param {float} [$price] the $price per $outcome token between 0 and 1; required for limit orders and market SELL orders (where it acts reference / worst acceptable $price for the taker $amount); ignored for market BUY orders ($amount is already the quote to spend)
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @param {bool} [$params->postOnly] limit orders only - reject the $order if it would cross the spread
         * @return {array} a [prediction $order structure](https://docs.ccxt.com/#/?id=prediction-$order-structure)
         */
        Async\await($this->load_api_key());
        $this->check_required_credentials();
        $outcomeObj = Async\await($this->load_outcome($outcome));
        $tokenId = $outcomeObj['outcomeId'];
        $isMarket = ($type === 'market');
        $sideStr = strtoupper($side);
        if ($price === null) {
            if (!$isMarket) {
                throw new ArgumentsRequired($this->id . ' createOrder() requires a $price for limit orders');
            }
            if ($sideStr === 'SELL') {
                // the reference (worst acceptable) $price the taker $amount is computed from
                throw new ArgumentsRequired($this->id . ' createOrder() requires a $price for market sell orders');
            }
        }
        $marketOrderPrice = '0';
        if ($isMarket && ($sideStr === 'SELL')) {
            $marketOrderPrice = $this->number_to_string($price);
        }
        $info = $this->safe_dict($outcomeObj, 'info', array());
        $topicId = $this->safe_integer($info, 'marketId');
        $quoteTokenAddress = $this->safe_string($info, 'quoteToken');
        $quoteToken = Async\await($this->load_quote_token($quoteTokenAddress));
        $exchangeAddress = $this->safe_string($quoteToken, 'ctfExchangeAddress', '');
        $decimals = $this->safe_integer($quoteToken, 'decimal', 18);
        $amounts = $this->opinion_order_raw_amounts($isMarket, $sideStr, $amount, $price, $decimals);
        $makerAmount = $this->safe_string($amounts, 'makerAmount');
        $takerAmount = $this->safe_string($amounts, 'takerAmount');
        $sideInt = ($sideStr === 'BUY') ? 0 : 1;
        $salt = $this->number_to_string($this->milliseconds());
        $postOnly = $this->safe_bool($params, 'postOnly', false);
        $rest = $this->omit($params, array( 'postOnly' ));
        $maker = Async\await($this->load_multi_sign_address());
        // Ethereum addresses are case-insensitive - a checksummed multiSignAddress compared
        // against a differently-cased walletAddress with strict equality would pick the wrong
        // $signatureType (0 EOA vs 2 Gnosis Safe) and break $order signing/validation
        $makerLower = strtolower($maker);
        $walletAddressLower = strtolower($this->walletAddress);
        $signatureType = ($makerLower === $walletAddressLower) ? 0 : 2;
        $order = array(
            'salt' => $salt,
            'maker' => $maker,
            'signer' => $this->walletAddress,
            'taker' => '0x0000000000000000000000000000000000000000',
            'tokenId' => $tokenId,
            'makerAmount' => $makerAmount,
            'takerAmount' => $takerAmount,
            'expiration' => '0',
            'nonce' => '0',
            'feeRateBps' => '0',
            'side' => $sideInt,
            'signatureType' => $signatureType,
        );
        $signature = $this->sign_opinion_order($order, $exchangeAddress);
        $signatureNo0x = $this->remove0x_prefix($signature);
        $orderBody = $this->extend(array(
            'salt' => $salt,
            'maker' => $maker,
            'signer' => $this->walletAddress,
            'taker' => '0x0000000000000000000000000000000000000000',
            'tokenId' => $tokenId,
            'makerAmount' => $makerAmount,
            'takerAmount' => $takerAmount,
            'expiration' => '0',
            'nonce' => '0',
            'feeRateBps' => '0',
            'side' => (string) $sideInt,
            'signatureType' => (string) $signatureType,
            'signature' => $signature,
            'sign' => mb_substr($signatureNo0x, 0, 64 - 0),
            'contractAddress' => '',
            'currencyAddress' => $quoteTokenAddress,
            'topicId' => $topicId,
            'price' => $isMarket ? $marketOrderPrice : $this->number_to_string($price),
            'tradingMethod' => $isMarket ? 1 : 2,
            'timestamp' => $this->seconds(),
            'safeRate' => '0',
            'orderExpTime' => '0',
            'postOnly' => $postOnly,
        ), $rest);
        $response = Async\await($this->opinionPrivatePostOrder($orderBody));
        $result = $this->safe_dict($response, 'result', array());
        $orderData = $this->safe_dict($result, 'orderData', array());
        return $this->parse_prediction_order($orderData, $outcomeObj);
    }

    public function cancel_order(?string $id, ?string $outcome = null, $params = array()): PromiseInterface {
        return Async\async(self::do_cancel_order(...))($id, $outcome, $params);
    }

    private function do_cancel_order(?string $id, ?string $outcome = null, $params = array()) {
        /**
         * cancels a single open order by $id
         *
         * @see https://docs.opinion.trade/developer-guide/opinion-open-api/order
         *
         * @param {string} $id the order $id
         * @param {string} [$outcome] not used by opinion cancelOrder
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a [prediction order structure](https://docs.ccxt.com/#/?$id=prediction-order-structure)
         */
        Async\await($this->load_api_key());
        $request = array( 'orderId' => $id );
        $response = Async\await($this->opinionPrivatePostOrderCancel($this->extend($request, $params)));
        $result = $this->safe_dict($response, 'result', array());
        $canceled = $this->safe_bool($result, 'result', false);
        // a false $result does NOT mean the order is still open — it may already be filled,
        // already cancelled, or unknown; don't invent a $status the venue didn't report.
        // error responses with an errno never reach this line, handleErrors throws on them
        $status = ($canceled) ? 'canceled' : null;
        return $this->safe_prediction_order(array( 'id' => $id, 'status' => $status, 'info' => $response ));
    }

    public function parse_order_status(?string $status): ?string {
        /**
         * @ignore
         * maps an opinion order statusEnum string to the unified $status vocabulary
         * @param {string} $status the raw opinion order statusEnum
         * @return {string} a unified order $status
         */
        $statuses = array(
            'Pending' => 'open',
            'Finished' => 'closed',
            'Canceled' => 'canceled',
            'Expired' => 'canceled',
            'Failed' => 'canceled',
        );
        return $this->safe_string($statuses, $status, $status);
    }

    public function parse_prediction_order(array $order, ?array $market = null): array {
        /**
         * parses a raw opinion $order object into a unified prediction $order structure
         * @param {array} $order the raw opinion OrderData object
         * @param {array} [$market] the outcome object the $order belongs to
         * @return {array} a [prediction $order structure](https://docs.ccxt.com/#/?$id=prediction-$order-structure)
         */
        //
        //     {
        //         "orderId" => "...",
        //         "marketId" => 1094,
        //         "side" => 0,
        //         "sideEnum" => "Buy",
        //         "tradingMethod" => 2,
        //         "tradingMethodEnum" => "Limit",
        //         "price" => "0.01",
        //         "orderShares" => "5",
        //         "orderAmount" => "0.05",
        //         "filledShares" => "0",
        //         "filledAmount" => "0",
        //         "profit" => "0",
        //         "status" => 1,
        //         "statusEnum" => "Pending",
        //         "createdAt" => 1785500000,
        //         "expiresAt" => 0,
        //         "postOnly" => false
        //     }
        //
        $id = $this->safe_string($order, 'orderId');
        $marketAny = $market;
        $statusEnum = $this->safe_string($order, 'statusEnum');
        $status = $this->parse_order_status($statusEnum);
        $sideEnum = $this->safe_string_lower($order, 'sideEnum');
        $tradingMethodEnum = $this->safe_string_lower($order, 'tradingMethodEnum');
        $timestamp = $this->safe_timestamp($order, 'createdAt');
        return $this->safe_prediction_order(array(
            'id' => $id,
            'clientOrderId' => null,
            'info' => $order,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'lastTradeTimestamp' => null,
            'status' => $status,
            'outcome' => $this->safe_string($marketAny, 'outcome'),
            'outcomeId' => $this->safe_string_2($marketAny, 'outcomeId', 'id'),
            'label' => $this->safe_string($marketAny, 'label'),
            'market' => $this->safe_string_2($marketAny, 'market', 'outcome'),
            'type' => $tradingMethodEnum,
            'side' => $sideEnum,
            'price' => $this->safe_number($order, 'price'),
            'amount' => $this->safe_number($order, 'orderShares'),
            // cost is the FILLED portion's collateral (unified cost = filled * price) — orderAmount
            // is the full requested orderShares * price, wrong for a partially filled $order
            'cost' => $this->safe_number($order, 'filledAmount'),
            'filled' => $this->safe_number($order, 'filledShares'),
            'fee' => null,
            'trades' => array(),
        ), $market);
    }

    public function fetch_orders(?string $outcome = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_orders(...))($outcome, $since, $limit, $params);
    }

    private function do_fetch_orders(?string $outcome = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches all of the authenticated user's $orders
         *
         * @see https://docs.opinion.trade/developer-guide/opinion-open-api/order
         *
         * @param {string} [$outcome] filter by unified $outcome or $outcome token id
         * @param {int} [$since] timestamp in ms of the earliest order to fetch
         * @param {int} [$limit] the maximum number of $orders to fetch
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} a list of [prediction order structures](https://docs.ccxt.com/#/?id=prediction-order-structure)
         */
        Async\await($this->load_api_key());
        $outcomeObj = null;
        $request = array();
        if ($outcome !== null) {
            $outcomeObj = Async\await($this->load_outcome($outcome));
            $info = $this->safe_dict($outcomeObj, 'info', array());
            $request['marketId'] = $this->safe_integer($info, 'marketId');
        }
        $response = Async\await($this->opinionPrivateGetOrder($this->extend($request, $params)));
        $result = $this->safe_dict($response, 'result', array());
        $orders = $this->safe_list($result, 'list', array());
        return $this->parse_prediction_orders($orders, $outcomeObj, $since, $limit);
    }

    public function fetch_order(?string $id, ?string $outcome = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_order(...))($id, $outcome, $params);
    }

    private function do_fetch_order(?string $id, ?string $outcome = null, $params = array()) {
        /**
         * fetches a single order by $id
         *
         * @see https://docs.opinion.trade/developer-guide/opinion-open-api/order
         *
         * @param {string} $id the order $id
         * @param {string} [$outcome] unified $outcome or $outcome token $id
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a [prediction order structure](https://docs.ccxt.com/#/?$id=prediction-order-structure)
         */
        Async\await($this->load_api_key());
        $outcomeObj = null;
        if ($outcome !== null) {
            $outcomeObj = Async\await($this->load_outcome($outcome));
        }
        $response = Async\await($this->opinionPrivateGetOrderOrderId($this->extend(array( 'orderId' => $id ), $params)));
        $result = $this->safe_dict($response, 'result', array());
        $orderData = $this->safe_dict($result, 'orderData', array());
        return $this->parse_prediction_order($orderData, $outcomeObj);
    }

    public function fetch_open_orders(?string $outcome = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_open_orders(...))($outcome, $since, $limit, $params);
    }

    private function do_fetch_open_orders(?string $outcome = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches the authenticated user's open orders
         *
         * @see https://docs.opinion.trade/developer-guide/opinion-open-api/order
         *
         * @param {string} [$outcome] filter by unified $outcome or $outcome token id
         * @param {int} [$since] timestamp in ms of the earliest order to fetch
         * @param {int} [$limit] the maximum number of orders to fetch
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} a list of [prediction order structures](https://docs.ccxt.com/#/?id=prediction-order-structure)
         */
        // 1 = pending - open status
        $request = array( 'status' => '1' );
        return Async\await($this->fetch_orders($outcome, $since, $limit, $this->extend($request, $params)));
    }

    public function fetch_closed_orders(?string $outcome = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_closed_orders(...))($outcome, $since, $limit, $params);
    }

    private function do_fetch_closed_orders(?string $outcome = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches the authenticated user's closed orders
         *
         * @see https://docs.opinion.trade/developer-guide/opinion-open-api/order
         *
         * @param {string} [$outcome] filter by unified $outcome or $outcome token id
         * @param {int} [$since] timestamp in ms of the earliest order to fetch
         * @param {int} [$limit] the maximum number of orders to fetch
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} a list of [prediction order structures](https://docs.ccxt.com/#/?id=prediction-order-structure)
         */
        // 2 = filled, 3 = canceled, 4 = expired, 5 = failed
        $request = array( 'status' => '2,3,4,5' );
        return Async\await($this->fetch_orders($outcome, $since, $limit, $this->extend($request, $params)));
    }

    public function fetch_my_trades(?string $outcome = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_my_trades(...))($outcome, $since, $limit, $params);
    }

    private function do_fetch_my_trades(?string $outcome = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * fetches the authenticated user's $trades
         *
         * @see https://docs.opinion.trade/developer-guide/opinion-open-api/trade
         *
         * @param {string} [$outcome] filter by unified $outcome or $outcome token id
         * @param {int} [$since] timestamp in ms of the earliest $trade to fetch
         * @param {int} [$limit] the maximum number of $trades to fetch
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} a list of [prediction $trade structures](https://docs.ccxt.com/#/?id=prediction-$trade-structure)
         */
        if ($this->walletAddress === null) {
            throw new ArgumentsRequired($this->id . ' fetchMyTrades() requires a walletAddress');
        }
        Async\await($this->load_api_key());
        $outcomeObj = null;
        $request = array( 'walletAddress' => $this->walletAddress );
        if ($outcome !== null) {
            $outcomeObj = Async\await($this->load_outcome($outcome));
            $info = $this->safe_dict($outcomeObj, 'info', array());
            $request['marketId'] = $this->safe_integer($info, 'marketId');
        }
        $response = Async\await($this->opinionPrivateGetTradeUserWalletAddress($this->extend($request, $params)));
        $result = $this->safe_dict($response, 'result', array());
        $trades = $this->safe_list($result, 'list', array());
        $tradesLength = count($trades);
        for ($i = 0; $i < $tradesLength; $i++) {
            $trade = $trades[$i];
            $tokenId = $this->safe_string($trade, 'tokenId');
            $marketId = $this->safe_integer($trade, 'marketId');
            if (($tokenId === null) && ($marketId !== null)) {
                $tradeMarket = Async\await($this->load_trade_market($marketId));
                $info = $this->safe_dict($tradeMarket, 'info', array());
                $isYes = ($this->safe_string_lower($trade, 'outcomeSideEnum') === 'yes');
                $trade['tokenId'] = $isYes ? $this->safe_string($info, 'yesTokenId') : $this->safe_string($info, 'noTokenId');
            }
        }
        return $this->parse_prediction_trades($trades, $outcomeObj, $since, $limit);
    }

    public function load_trade_market(?int $marketId): PromiseInterface {
        return Async\async(self::do_load_trade_market(...))($marketId);
    }

    private function do_load_trade_market(?int $marketId) {
        /**
         * @ignore
         * fetches and caches a single $market by its numeric $marketId, and indexes its outcomes
         * @param {int} $marketId the numeric $market id
         * @return {array} the parsed $market
         */
        if ($marketId === null) {
            throw new ArgumentsRequired($this->id . ' loadTradeMarket() requires a marketId');
        }
        $cacheKey = 'tradeMarketsById';
        $cached = $this->safe_dict($this->options, $cacheKey, array());
        $idStr = (string) $marketId;
        $existing = $this->safe_dict($cached, $idStr);
        if ($existing !== null) {
            return $existing;
        }
        $response = Async\await($this->opinionPublicGetMarketMarketId(array( 'marketId' => $marketId )));
        $result = $this->safe_dict($response, 'result', array());
        $data = $this->safe_dict($result, 'data', array());
        $market = $this->parse_opinion_market($data);
        if ($market === null) {
            throw new ExchangeError($this->id . ' loadTradeMarket() could not parse $market ' . $idStr);
        }
        if ($this->markets === null) {
            $this->markets = $this->create_safe_dictionary();
        }
        $marketHandle = $this->safe_string($market, 'market', '');
        $this->markets[$marketHandle] = $market;
        $this->index_market_outcomes($market);
        $cached[$idStr] = $market;
        $this->options[$cacheKey] = $cached;
        return $market;
    }

    public function parse_prediction_trade(array $trade, ?array $market = null): array {
        /**
         * @ignore
         * parses a raw opinion $trade object into a unified $trade object
         * @param {array} $trade the raw opinion TradeData object
         * @param {array} [$market] the outcome object the $trade belongs to
         * @return {array} a [prediction $trade structure](https://docs.ccxt.com/#/?id=prediction-$trade-structure)
         */
        $tokenId = $this->safe_string($trade, 'tokenId');
        $outcomeObj = $this->safe_outcome($tokenId, $market);
        $timestamp = $this->safe_timestamp($trade, 'createdAt');
        $side = $this->safe_string_lower($trade, 'side');
        return $this->safe_prediction_trade(array(
            'id' => $this->safe_string($trade, 'txHash'),
            'timestamp' => $timestamp,
            'side' => $side,
            'price' => $this->safe_number($trade, 'price'),
            'amount' => $this->safe_number($trade, 'shares'),
            'cost' => $this->safe_number($trade, 'amount'),
            'fee' => array(
                'cost' => $this->safe_number($trade, 'fee'),
                'currency' => 'USDT',
            ),
            'outcome' => $this->safe_string($outcomeObj, 'outcome'),
            'outcomeId' => $this->safe_string_2($outcomeObj, 'outcomeId', 'id'),
            'label' => $this->safe_string($outcomeObj, 'label'),
            'market' => $this->safe_string_2($outcomeObj, 'market', 'outcome'),
        ));
    }

    public function fetch_balance($params = array()): PromiseInterface {
        return Async\async(self::do_fetch_balance(...))($params);
    }

    private function do_fetch_balance($params = array()) {
        /**
         * fetches the authenticated user's quote-token balances
         *
         * @see https://docs.opinion.trade/developer-guide/opinion-open-api/quote-token
         *
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a [balance structure](https://docs.ccxt.com/#/?id=balance-structure)
         */
        Async\await($this->load_api_key());
        $request = array( 'chain_id' => '56' );
        $response = Async\await($this->opinionPrivateGetUserBalance($this->extend($request, $params)));
        $result = $this->safe_dict($response, 'result', array());
        $rawBalances = $this->safe_list($result, 'balances', array());
        $rawBalancesLength = count($rawBalances);
        for ($i = 0; $i < $rawBalancesLength; $i++) {
            $rawBalance = $rawBalances[$i];
            $quoteTokenAddress = $this->safe_string($rawBalance, 'quoteToken');
            $quoteToken = Async\await($this->load_quote_token($quoteTokenAddress));
            $rawBalance['symbol'] = $this->safe_string($quoteToken, 'symbol', 'USDT');
        }
        return $this->parse_balance($response);
    }

    public function parse_balance(mixed $response): array {
        /**
         * @ignore
         * parses an opinion user-$balance $response into a unified $balances object
         * @param {array} $response the raw user-$balance $response
         * @return {array} a [$balance structure](https://docs.ccxt.com/#/?id=$balance-structure)
         */
        $result = array( 'info' => $response );
        $data = $this->safe_dict($response, 'result', array());
        $balances = $this->safe_list($data, 'balances', array());
        $balancesLength = count($balances);
        for ($i = 0; $i < $balancesLength; $i++) {
            $balance = $balances[$i];
            $code = $this->safe_string($balance, 'symbol', 'USDT');
            $result[$code] = array(
                'free' => $this->safe_number($balance, 'availableBalance'),
                'used' => $this->safe_number($balance, 'frozenBalance'),
                'total' => $this->safe_number($balance, 'totalBalance'),
            );
        }
        return $this->safe_balance($result);
    }

    public function fetch_positions(?array $outcomes = null, $params = array()): PromiseInterface {
        return Async\async(self::do_fetch_positions(...))($outcomes, $params);
    }

    private function do_fetch_positions(?array $outcomes = null, $params = array()) {
        /**
         * fetches the authenticated user's open $positions
         *
         * @see https://docs.opinion.trade/developer-guide/opinion-open-api/position
         *
         * @param {string[]} [$outcomes] filter by unified $outcomes or outcome token ids
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} a list of [prediction $position structures](https://docs.ccxt.com/#/?id=prediction-$position-structure)
         */
        if ($this->walletAddress === null) {
            throw new ArgumentsRequired($this->id . ' fetchPositions() requires a walletAddress');
        }
        Async\await($this->load_api_key());
        $outcomesLength = 0;
        if ($outcomes !== null) {
            $outcomesLength = count($outcomes);
            Async\await($this->load_outcomes($outcomes));
        }
        $request = array( 'walletAddress' => $this->walletAddress );
        $response = Async\await($this->opinionPrivateGetPositionsUserWalletAddress($this->extend($request, $params)));
        $result = $this->safe_dict($response, 'result', array());
        $positions = $this->safe_list($result, 'list', array());
        $parsed = $this->parse_prediction_positions($positions);
        if ($outcomesLength === 0) {
            return $parsed;
        }
        $wantedTokenIds = array();
        // copy to a plain list so the strict null checks see one shape
        $outcomesList = ($outcomes === null) ? array() : $outcomes;
        for ($i = 0; $i < count($outcomesList); $i++) {
            $outcomeObj = $this->outcome($outcomesList[$i]);
            $tokenId = $this->safe_string($outcomeObj, 'outcomeId');
            if ($tokenId !== null) {
                $wantedTokenIds[$tokenId] = true;
            }
        }
        $filtered = array();
        for ($i = 0; $i < count($parsed); $i++) {
            $position = $parsed[$i];
            $info = $this->safe_dict($position, 'info', array());
            $tokenId = $this->safe_string($info, 'tokenId');
            if (($tokenId !== null) && (is_array($wantedTokenIds) && array_key_exists($tokenId ?? '', $wantedTokenIds))) {
                $filtered[] = $position;
            }
        }
        return $filtered;
    }

    public function parse_prediction_position(array $position, ?array $market = null): array {
        /**
         * @ignore
         * parses a raw opinion $position object into a unified $position object
         * @param {array} $position the raw opinion PositionData object
         * @param {array} [$market] the outcome object the $position belongs to
         * @return {array} a [prediction $position structure](https://docs.ccxt.com/#/?id=prediction-$position-structure)
         */
        $tokenId = $this->safe_string($position, 'tokenId');
        $outcomeObj = $this->safe_outcome($tokenId, $market);
        $outcomeSideEnum = $this->safe_string_lower($position, 'outcomeSideEnum');
        return $this->safe_prediction_position(array(
            'contracts' => $this->safe_number($position, 'sharesOwned'),
            'side' => $outcomeSideEnum,
            'unrealizedPnl' => $this->safe_number($position, 'unrealizedPnl'),
            'entryPrice' => $this->safe_number($position, 'avgEntryPrice'),
            'outcome' => $this->safe_string($outcomeObj, 'outcome'),
            'outcomeId' => $this->safe_string_2($outcomeObj, 'outcomeId', 'id'),
            'label' => $this->safe_string($outcomeObj, 'label'),
            'market' => $this->safe_string_2($outcomeObj, 'market', 'outcome'),
            'info' => $position,
        ));
    }

    public function hash_message(mixed $message): string {
        return '0x' . $this->hash($message, 'keccak', 'hex');
    }

    public function sign_hash(string $hash, string $privateKey): array {
        $signature = $this->ecdsa(mb_substr($hash, -64), mb_substr($privateKey, -64), 'secp256k1', null);
        // assign before padStart so the PHP str_pad regex matches
        $rRaw = $signature['r'];
        $sRaw = $signature['s'];
        $r = str_pad($rRaw, 64, '0', STR_PAD_LEFT);
        $s = str_pad($sRaw, 64, '0', STR_PAD_LEFT);
        return array(
            'r' => '0x' . $r,
            's' => '0x' . $s,
            'v' => $this->sum(27, $signature['v']),
        );
    }

    public function sign_message(mixed $message, string $privateKey): array {
        return $this->sign_hash($this->hash_message($message), mb_substr($privateKey, -64));
    }

    public function sign_api_key_auth(string $walletAddress, string $action, string $timestamp): string {
        // EIP-712 signature used to create/get/delete an API key (wallet-authenticated key management)
        $domain = array(
            'name' => 'Opinion OpenAPI',
            'version' => '1',
            'chainId' => 56,
        );
        $messageTypes = array(
            'OpinionApiKeyAuth' => array(
                array( 'name' => 'walletAddress', 'type' => 'address' ),
                array( 'name' => 'action', 'type' => 'string' ),
                array( 'name' => 'timestamp', 'type' => 'string' ),
            ),
        );
        $messageData = array(
            'walletAddress' => $walletAddress,
            'action' => $action,
            'timestamp' => $timestamp,
        );
        $encoded = $this->eth_encode_structured_data($domain, $messageTypes, $messageData);
        $sig = $this->sign_message($encoded, $this->privateKey);
        return '0x' . $this->remove0x_prefix($sig['r']) . $this->remove0x_prefix($sig['s']) . $this->int_to_base16($sig['v']);
    }

    public function create_api_key($params = array()): PromiseInterface {
        return Async\async(self::do_create_api_key(...))($params);
    }

    private function do_create_api_key($params = array()) {
        /**
         * self-service creation of an Open API key linked to $this->walletAddress via
         * an EIP-712-signed request - there is no "generate key" button in the Opinion GUI, this is
         * the only documented way to obtain a wallet-linked key
         *
         * @see https://docs.opinion.trade/developer-guide/opinion-open-api/authentication
         *
         * @param {array} [$params] extra parameters
         * @return {array} the api credentials array( apiKey, walletAddress )
         */
        $response = Async\await($this->opinionPrivatePostAuthApiKey($params));
        $result = $this->safe_dict($response, 'result', array());
        return $this->set_api_credentials($result);
    }

    public function fetch_api_key($params = array()): PromiseInterface {
        return Async\async(self::do_fetch_api_key(...))($params);
    }

    private function do_fetch_api_key($params = array()) {
        /**
         * fetches the currently active Open API key for $this->walletAddress
         *
         * @see https://docs.opinion.trade/developer-guide/opinion-open-api/authentication
         *
         * @param {array} [$params] extra parameters
         * @return {array} the api credentials array( apiKey, walletAddress )
         */
        $response = Async\await($this->opinionPrivateGetAuthApiKey($params));
        $result = $this->safe_dict($response, 'result', array());
        return $this->set_api_credentials($result);
    }

    public function delete_api_key($params = array()): PromiseInterface {
        return Async\async(self::do_delete_api_key(...))($params);
    }

    private function do_delete_api_key($params = array()) {
        /**
         * revokes the Open API key for $this->walletAddress
         *
         * @see https://docs.opinion.trade/developer-guide/opinion-open-api/authentication
         *
         * @param {array} [$params] extra parameters
         * @return {array} raw $response, result.deleted confirms revocation
         */
        $response = Async\await($this->opinionPrivateDeleteAuthApiKey($params));
        $this->options['apiKey'] = null;
        // sign() prefers $this->apiKey over options['apiKey'] - clear it too, or a directly-set
        // exchange.apiKey would keep being used for private calls after the key is revoked.
        // an empty string, not null => the strict base types the credential, and
        // sign() treats an empty key
        $this->apiKey = '';
        return $response;
    }

    public function load_api_key(): PromiseInterface {
        return Async\async(self::do_load_api_key(...))();
    }

    private function do_load_api_key() {
        /**
         * @ignore
         * ensures an apiKey is available before a private call - reuses a directly-set key, otherwise
         * self-issues one from the walletAddress/privateKey via fetchApiKey(), falling back to createApiKey() when
         * the wallet has no key yet; freshly created keys can take ~15 seconds to activate venue-side
         * @return {string} the apiKey
         */
        $hasDirectApiKey = !$this->is_empty_string($this->apiKey);
        if ($hasDirectApiKey) {
            return $this->apiKey;
        }
        $optionsKey = $this->safe_string($this->options, 'apiKey');
        if ($optionsKey !== null) {
            return $optionsKey;
        }
        if (($this->walletAddress === null) || ($this->privateKey === null)) {
            throw new AuthenticationError($this->id . ' private endpoints require an apiKey, or a walletAddress and privateKey to self-issue one');
        }
        $creds = null;
        try {
            $creds = Async\await($this->fetch_api_key());
        } catch (Exception $e) {
            // no key exists for this wallet yet (11010) - self-issue one; any other
            // failure (unregistered wallet, disabled issuance) surfaces from the create call
            $creds = Async\await($this->create_api_key());
        }
        return $this->safe_string($creds, 'apiKey');
    }

    public function set_api_credentials(array $response): array {
        //
        //     array( "apiKey" => "...", "walletAddress" => "..." )
        //
        $creds = array(
            'apiKey' => $this->safe_string($response, 'apiKey'),
            'walletAddress' => $this->safe_string($response, 'walletAddress'),
        );
        $this->options['apiKey'] = $creds['apiKey'];
        // checkRequiredCredentials() (called by createOrder()) checks $this->apiKey, not
        // options['apiKey'] - keep both in sync, same() clearing both
        $this->apiKey = $creds['apiKey'];
        return $creds;
    }

    public function opinion_ws_url(): string {
        /**
         * @ignore
         * builds the websocket url - the venue authenticates the whole connection with the $apiKey passed query parameter, for public and private channels alike
         * @return {string} the websocket url
         */
        $hasDirectApiKey = !$this->is_empty_string($this->apiKey);
        $apiKey = ($hasDirectApiKey) ? $this->apiKey : $this->safe_string($this->options, 'apiKey');
        if ($apiKey === null) {
            throw new AuthenticationError($this->id . ' websocket requires an $apiKey - set it directly or call createApiKey()/fetchApiKey() first');
        }
        $wsUrl = $this->safe_string($this->urls['api'], 'ws', '');
        return $wsUrl . '?apikey=' . $apiKey;
    }

    public function ping(mixed $client) {
        // the venue keeps the socket open only while application-level heartbeats arrive
        return array( 'action' => 'HEARTBEAT' );
    }

    public function subscribe_opinion_channel(string $messageHash, string $channel, ?int $marketId): PromiseInterface {
        return Async\async(self::do_subscribe_opinion_channel(...))($messageHash, $channel, $marketId);
    }

    private function do_subscribe_opinion_channel(string $messageHash, string $channel, ?int $marketId) {
        /**
         * @ignore
         * subscribes to one venue $channel scoped by the binary $marketId and waits on the given message hash
         * @param {string} $messageHash the internal hash the awaited payload resolves on
         * @param {string} $channel the venue $channel name (e.g. 'market.depth.diff')
         * @param {int} $marketId the numeric binary market id
         * @return {any} the first resolved payload
         */
        Async\await($this->load_api_key());
        $url = $this->opinion_ws_url();
        $subscriptionKey = $channel . ':' . $this->number_to_string($marketId);
        $subscribeMsg = array(
            'action' => 'SUBSCRIBE',
            'channel' => $channel,
            'marketId' => $marketId,
        );
        return Async\await($this->watch($url, $messageHash, $subscribeMsg, $subscriptionKey));
    }

    public function handle_message(mixed $client, mixed $message) {
        // every data payload carries its channel name in $msgType; frames without one -
        // subscribe acks and heartbeat echoes - carry nothing to route
        $msgType = $this->safe_string($message, 'msgType');
        if ($msgType === null) {
            return;
        }
        if ($msgType === 'market.depth.diff') {
            $this->handle_order_book($client, $message);
        } elseif ($msgType === 'market.last.price') {
            $this->handle_ticker($client, $message);
        } elseif ($msgType === 'market.last.trade') {
            $this->handle_trades($client, $message);
        } elseif ($msgType === 'trade.order.update') {
            $this->handle_order($client, $message);
        } elseif ($msgType === 'trade.record.new') {
            $this->handle_my_trade($client, $message);
        }
    }

    public function opinion_outcome_by_market_id_side(?int $marketId, ?int $outcomeSide): mixed {
        /**
         * @ignore
         * resolves a cached outcome object from the numeric $marketId . $outcomeSide (1 yes / 2 no) the user channels report instead of a tokenId - cache-only, returns null on a cold cache
         * @param {int} $marketId the numeric binary $market id
         * @param {int} $outcomeSide 1 for the yes token, 2 for the no token
         * @return {array} the outcome object, or null
         */
        if (($marketId === null) || ($this->markets === null)) {
            return null;
        }
        $marketKeys = is_array($this->markets) ? array_keys($this->markets) : array();
        $marketKeysLength = count($marketKeys);
        for ($i = 0; $i < $marketKeysLength; $i++) {
            $market = $this->markets[$marketKeys[$i]];
            $info = $this->safe_dict($market, 'info', array());
            if ($this->safe_integer($info, 'marketId') === $marketId) {
                $outcomes = $this->safe_list($market, 'outcomes', array());
                $index = ($outcomeSide === 2) ? 1 : 0;
                return $this->safe_dict($outcomes, $index);
            }
        }
        return null;
    }

    public function watch_order_book(string $outcome, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_watch_order_book(...))($outcome, $limit, $params);
    }

    private function do_watch_order_book(string $outcome, ?int $limit = null, $params = array()) {
        /**
         * streams the order book of an $outcome token; the $channel is delta-only so the live book is seeded from the REST snapshot
         *
         * @see https://docs.opinion.trade/developer-guide/opinion-websocket/market-channels
         *
         * @param {string} $outcome unified $outcome or $outcome token id
         * @param {int} [$limit] the maximum number of order book entries to return
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a [prediction order book structure](https://docs.ccxt.com/#/?id=prediction-order-book-structure)
         */
        $outcomeObj = Async\await($this->load_outcome($outcome));
        $info = $this->safe_dict($outcomeObj, 'info', array());
        $marketId = $this->safe_integer($info, 'marketId');
        $sym = $this->safe_outcome_symbol($outcome, $outcomeObj);
        $channel = 'market.depth.diff';
        $messageHash = 'orderbook::' . $sym;
        Async\await($this->load_api_key());
        $url = $this->opinion_ws_url();
        $client = $this->client($url);
        $subscriptionKey = $channel . ':' . $this->number_to_string($marketId);
        $isNewSubscription = $this->safe_value($client->subscriptions, $subscriptionKey) === null;
        if ($isNewSubscription) {
            Async\await($this->seed_order_book($outcome, $sym, $limit));
        }
        $subscribeMsg = array(
            'action' => 'SUBSCRIBE',
            'channel' => $channel,
            'marketId' => $marketId,
        );
        $future = $this->watch($url, $messageHash, $subscribeMsg, $subscriptionKey);
        if ($isNewSubscription) {
            // return the freshly-seeded book immediately instead of blocking until the next delta
            $client->resolve($this->safe_value($this->orderbooks, $sym), $messageHash);
        }
        $orderbook = Async\await($future);
        return $orderbook->limit();
    }

    public function seed_order_book(?string $outcome, ?string $sym, ?int $limit = null) {
        return Async\async(self::do_seed_order_book(...))($outcome, $sym, $limit);
    }

    private function do_seed_order_book(?string $outcome, ?string $sym, ?int $limit = null) {
        // the depth channel streams single-level deltas only, so seed the live book from the REST $snapshot
        $snapshot = Async\await($this->fetch_order_book($outcome, $limit));
        $orderbook = $this->order_book(array());
        $orderbook->reset($snapshot);
        $this->orderbooks[$sym] = $orderbook;
    }

    public function handle_order_book(mixed $client, mixed $message) {
        //
        //     {
        //         "marketId" => 2764,
        //         "tokenId" => "19120407572139442221452465677574895365338028945317996490376653704877573103648",
        //         "outcomeSide" => 1,
        //         "side" => "bids",
        //         "price" => "0.2",
        //         "size" => "50",
        //         "msgType" => "market.depth.diff"
        //     }
        //
        $tokenId = $this->safe_string($message, 'tokenId');
        $outcomeObj = $this->safe_dict($this->outcomes_by_id, $tokenId);
        $sym = $this->safe_string($outcomeObj, 'outcome');
        if ($sym === null) {
            return;
        }
        if ($this->safe_value($this->orderbooks, $sym) === null) {
            // the delta belongs to the market's other token, whose book is not being watched
            return;
        }
        $orderbook = $this->orderbooks[$sym];
        $sideStr = $this->safe_string($message, 'side');
        $bookSide = ($sideStr === 'bids') ? $orderbook['bids'] : $orderbook['asks'];
        $price = $this->safe_number($message, 'price');
        $size = $this->safe_number($message, 'size');
        $bookSide->storeArray(array( $price, $size ));
        $now = $this->milliseconds();
        $orderbook['timestamp'] = $now;
        $orderbook['datetime'] = $this->iso8601($now);
        $client->resolve($orderbook, 'orderbook::' . $sym);
    }

    public function watch_ticker(string $outcome, $params = array()): PromiseInterface {
        return Async\async(self::do_watch_ticker(...))($outcome, $params);
    }

    private function do_watch_ticker(string $outcome, $params = array()) {
        /**
         * streams last-price updates of an $outcome token
         *
         * @see https://docs.opinion.trade/developer-guide/opinion-websocket/market-channels
         *
         * @param {string} $outcome unified $outcome or $outcome token id
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array} a [prediction ticker structure](https://docs.ccxt.com/#/?id=prediction-ticker-structure)
         */
        $outcomeObj = Async\await($this->load_outcome($outcome));
        $info = $this->safe_dict($outcomeObj, 'info', array());
        $marketId = $this->safe_integer($info, 'marketId');
        $sym = $this->safe_outcome_symbol($outcome, $outcomeObj);
        $messageHash = 'ticker::' . $sym;
        return Async\await($this->subscribe_opinion_channel($messageHash, 'market.last.price', $marketId));
    }

    public function handle_ticker(mixed $client, mixed $message) {
        //
        //     {
        //         "tokenId" => "19120407572139442221452465677574895365338028945317996490376653704877573103648",
        //         "outcomeSide" => 1,
        //         "price" => "0.85",
        //         "marketId" => 2764,
        //         "msgType" => "market.last.price"
        //     }
        //
        $tokenId = $this->safe_string($message, 'tokenId');
        $outcomeObj = $this->safe_dict($this->outcomes_by_id, $tokenId);
        $sym = $this->safe_string($outcomeObj, 'outcome');
        if ($sym === null) {
            return;
        }
        $now = $this->milliseconds();
        $last = $this->safe_number($message, 'price');
        $ticker = $this->safe_prediction_ticker(array(
            'outcome' => $sym,
            'outcomeId' => $tokenId,
            'label' => $this->safe_string($outcomeObj, 'label'),
            'market' => $this->safe_string($outcomeObj, 'market'),
            'timestamp' => $now,
            'datetime' => $this->iso8601($now),
            'close' => $last,
            'last' => $last,
            'info' => $message,
        ), $outcomeObj);
        $this->tickers[$sym] = $ticker;
        $client->resolve($ticker, 'ticker::' . $sym);
    }

    public function watch_trades(string $outcome, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_watch_trades(...))($outcome, $since, $limit, $params);
    }

    private function do_watch_trades(string $outcome, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * streams public $trades of an $outcome token
         *
         * @see https://docs.opinion.trade/developer-guide/opinion-websocket/market-channels
         *
         * @param {string} $outcome unified $outcome or $outcome token id
         * @param {int} [$since] timestamp in ms of the earliest trade to return
         * @param {int} [$limit] the maximum number of $trades to return
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} a list of [prediction trade structures](https://docs.ccxt.com/#/?id=prediction-trade-structure)
         */
        $outcomeObj = Async\await($this->load_outcome($outcome));
        $info = $this->safe_dict($outcomeObj, 'info', array());
        $marketId = $this->safe_integer($info, 'marketId');
        $sym = $this->safe_outcome_symbol($outcome, $outcomeObj);
        $messageHash = 'trades::' . $sym;
        $trades = Async\await($this->subscribe_opinion_channel($messageHash, 'market.last.trade', $marketId));
        return $this->filter_by_since_limit($trades, $since, $limit, 'timestamp', true);
    }

    public function handle_trades(mixed $client, mixed $message) {
        //
        //     {
        //         "tokenId" => "19120407572139442221452465677574895365338028945317996490376653704877573103648",
        //         "side" => "Buy",
        //         "outcomeSide" => 1,
        //         "price" => "0.85",
        //         "shares" => "10",
        //         "amount" => "8.5",
        //         "marketId" => 2764,
        //         "msgType" => "market.last.trade"
        //     }
        //
        $tokenId = $this->safe_string($message, 'tokenId');
        $outcomeObj = $this->safe_dict($this->outcomes_by_id, $tokenId);
        $sym = $this->safe_string($outcomeObj, 'outcome');
        if ($sym === null) {
            return;
        }
        $now = $this->milliseconds();
        $trade = $this->safe_prediction_trade(array(
            'id' => null,
            'info' => $message,
            'timestamp' => $now,
            'datetime' => $this->iso8601($now),
            'outcome' => $sym,
            'outcomeId' => $tokenId,
            'label' => $this->safe_string($outcomeObj, 'label'),
            'market' => $this->safe_string($outcomeObj, 'market'),
            'order' => null,
            'type' => null,
            'side' => $this->safe_string_lower($message, 'side'),
            'takerOrMaker' => 'taker',
            'price' => $this->safe_number($message, 'price'),
            'amount' => $this->safe_number($message, 'shares'),
            'cost' => $this->safe_number($message, 'amount'),
            'fee' => null,
        ), $outcomeObj);
        if ($this->trades === null) {
            $this->trades = $this->create_safe_dictionary();
        }
        if ($this->safe_value($this->trades, $sym) === null) {
            $tradesLimit = $this->safe_integer($this->options, 'tradesLimit', 1000);
            $this->trades[$sym] = new ArrayCache($tradesLimit);
        }
        $stored = $this->trades[$sym];
        $stored->append($trade);
        $client->resolve($stored, 'trades::' . $sym);
    }

    public function watch_orders(?string $outcome = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_watch_orders(...))($outcome, $since, $limit, $params);
    }

    private function do_watch_orders(?string $outcome = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * streams the authenticated user's order updates of one market - the venue channel is per-market, so the $outcome argument is required
         *
         * @see https://docs.opinion.trade/developer-guide/opinion-websocket/user-channels
         *
         * @param {string} $outcome unified $outcome or $outcome token id whose market to watch
         * @param {int} [$since] timestamp in ms of the earliest order to return
         * @param {int} [$limit] the maximum number of $orders to return
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} a list of [prediction order structures](https://docs.ccxt.com/#/?id=prediction-order-structure)
         */
        if ($outcome === null) {
            throw new ArgumentsRequired($this->id . ' watchOrders() requires an $outcome (the order update channel is per-market)');
        }
        $outcomeObj = Async\await($this->load_outcome($outcome));
        $info = $this->safe_dict($outcomeObj, 'info', array());
        $marketId = $this->safe_integer($info, 'marketId');
        $messageHash = 'orders';
        $orders = Async\await($this->subscribe_opinion_channel($messageHash, 'trade.order.update', $marketId));
        $sym = $this->safe_outcome_symbol($outcome, $outcomeObj);
        return $this->filter_by_value_since_limit($orders, 'outcome', $sym, $since, $limit, 'timestamp', true);
    }

    public function parse_ws_order_status(?int $status): ?string {
        /**
         * @ignore
         * maps the numeric order $status of the websocket order channel onto the unified vocabulary
         * @param {int} $status the numeric order $status
         * @return {string} a unified order $status, or null
         */
        // per the venue docs => 1 pending, 2 finished, 3 canceled, 4 expired, 5 failed
        if ($status === 1) {
            return 'open';
        }
        if ($status === 2) {
            return 'closed';
        }
        if ($status === 3) {
            return 'canceled';
        }
        if ($status === 4) {
            return 'expired';
        }
        if ($status === 5) {
            return 'rejected';
        }
        return null;
    }

    public function handle_order(mixed $client, mixed $message) {
        //
        //     {
        //         "orderUpdateType" => "orderConfirm",
        //         "marketId" => 2770,
        //         "rootMarketId" => 122,
        //         "orderId" => "a11ee07e-e22f-11f0-9714-0a58a9feac02",
        //         "side" => 1,
        //         "outcomeSide" => 1,
        //         "price" => "0.150000000000000000",
        //         "shares" => "66.66",
        //         "amount" => "9.999000000000000000",
        //         "status" => 1,
        //         "tradingMethod" => 2,
        //         "quoteToken" => "0x55d398326f99059fF775485246999027B3197955",
        //         "createdAt" => 1766735464,
        //         "expiresAt" => 0,
        //         "chainId" => "56",
        //         "filledShares" => "10.000000000000000000",
        //         "filledAmount" => "1.500000000000000000",
        //         "msgType" => "trade.order.update"
        //     }
        //
        $marketId = $this->safe_integer($message, 'marketId');
        $outcomeSide = $this->safe_integer($message, 'outcomeSide');
        $outcomeObj = $this->opinion_outcome_by_market_id_side($marketId, $outcomeSide);
        $timestamp = $this->safe_timestamp($message, 'createdAt');
        // unlike the REST $order body (0 buy / 1 sell), the websocket channel uses 1 buy / 2 sell
        // per the docs and confirmed live
        $sideInt = $this->safe_integer($message, 'side');
        $side = ($sideInt === 1) ? 'buy' : 'sell';
        $tradingMethod = $this->safe_integer($message, 'tradingMethod');
        $type = ($tradingMethod === 1) ? 'market' : 'limit';
        $order = $this->safe_prediction_order(array(
            'id' => $this->safe_string($message, 'orderId'),
            'clientOrderId' => null,
            'info' => $message,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'lastTradeTimestamp' => null,
            'status' => $this->parse_ws_order_status($this->safe_integer($message, 'status')),
            'outcome' => $this->safe_string($outcomeObj, 'outcome'),
            'outcomeId' => $this->safe_string($outcomeObj, 'outcomeId'),
            'label' => $this->safe_string($outcomeObj, 'label'),
            'market' => $this->safe_string($outcomeObj, 'market'),
            'type' => $type,
            'side' => $side,
            'price' => $this->safe_number($message, 'price'),
            'amount' => $this->safe_number($message, 'shares'),
            'cost' => $this->safe_number($message, 'filledAmount'),
            'filled' => $this->safe_number($message, 'filledShares'),
            'fee' => null,
            'trades' => array(),
        ), $outcomeObj);
        if ($this->orders === null) {
            $limit = $this->safe_integer($this->options, 'ordersLimit', 1000);
            $this->orders = new ArrayCacheByOutcomeById($limit);
        }
        $stored = $this->orders;
        $stored->append($order);
        $client->resolve($stored, 'orders');
    }

    public function watch_my_trades(?string $outcome = null, ?int $since = null, ?int $limit = null, $params = array()): PromiseInterface {
        return Async\async(self::do_watch_my_trades(...))($outcome, $since, $limit, $params);
    }

    private function do_watch_my_trades(?string $outcome = null, ?int $since = null, ?int $limit = null, $params = array()) {
        /**
         * streams the authenticated user's executed $trades of one market - the venue channel is per-market, so the $outcome argument is required
         *
         * @see https://docs.opinion.trade/developer-guide/opinion-websocket/user-channels
         *
         * @param {string} $outcome unified $outcome or $outcome token id whose market to watch
         * @param {int} [$since] timestamp in ms of the earliest trade to return
         * @param {int} [$limit] the maximum number of $trades to return
         * @param {array} [$params] extra parameters specific to the exchange API endpoint
         * @return {array[]} a list of [prediction trade structures](https://docs.ccxt.com/#/?id=prediction-trade-structure)
         */
        if ($outcome === null) {
            throw new ArgumentsRequired($this->id . ' watchMyTrades() requires an $outcome (the trade record channel is per-market)');
        }
        $outcomeObj = Async\await($this->load_outcome($outcome));
        $info = $this->safe_dict($outcomeObj, 'info', array());
        $marketId = $this->safe_integer($info, 'marketId');
        $messageHash = 'myTrades';
        $trades = Async\await($this->subscribe_opinion_channel($messageHash, 'trade.record.new', $marketId));
        $sym = $this->safe_outcome_symbol($outcome, $outcomeObj);
        return $this->filter_by_value_since_limit($trades, 'outcome', $sym, $since, $limit, 'timestamp', true);
    }

    public function handle_my_trade(mixed $client, mixed $message) {
        //
        //     {
        //         "orderId" => "3c7af25f-e21f-11f0-9714-0a58a9feac02",
        //         "tradeNo" => "e1403840-e22f-11f0-83af-0a58a9feac02",
        //         "marketId" => 2770,
        //         "rootMarketId" => 122,
        //         "txHash" => "0x272c...4195",
        //         "side" => "Buy",
        //         "outcomeSide" => 2,
        //         "price" => "0.100000000000000000",
        //         "shares" => "9.44444",
        //         "amount" => "0.944444",
        //         "profit" => "0.000000000000000000",
        //         "status" => 2,
        //         "quoteToken" => "0x55d398326f99059fF775485246999027B3197955",
        //         "fee" => "0.000000000000000000",
        //         "chainId" => "56",
        //         "createdAt" => 1766735571,
        //         "msgType" => "trade.record.new"
        //     }
        //
        $marketId = $this->safe_integer($message, 'marketId');
        $outcomeSide = $this->safe_integer($message, 'outcomeSide');
        $outcomeObj = $this->opinion_outcome_by_market_id_side($marketId, $outcomeSide);
        $sym = $this->safe_string($outcomeObj, 'outcome');
        $timestamp = $this->safe_timestamp($message, 'createdAt');
        $trade = $this->safe_prediction_trade(array(
            'id' => $this->safe_string($message, 'tradeNo'),
            'info' => $message,
            'timestamp' => $timestamp,
            'datetime' => $this->iso8601($timestamp),
            'outcome' => $sym,
            'outcomeId' => $this->safe_string($outcomeObj, 'outcomeId'),
            'label' => $this->safe_string($outcomeObj, 'label'),
            'market' => $this->safe_string($outcomeObj, 'market'),
            'order' => $this->safe_string($message, 'orderId'),
            'type' => null,
            'side' => $this->safe_string_lower($message, 'side'),
            'takerOrMaker' => null,
            'price' => $this->safe_number($message, 'price'),
            'amount' => $this->safe_number($message, 'shares'),
            'cost' => $this->safe_number($message, 'amount'),
            'fee' => array(
                'cost' => $this->safe_number($message, 'fee'),
                'currency' => 'USDT',
            ),
        ), $outcomeObj);
        if ($this->myTrades === null) {
            $myTradesLimit = $this->safe_integer($this->options, 'myTradesLimit', 1000);
            $this->myTrades = new ArrayCacheByOutcomeById($myTradesLimit);
        }
        $stored = $this->myTrades;
        $stored->append($trade);
        $client->resolve($stored, 'myTrades');
    }

    public function handle_errors(?int $code, string $reason, string $url, string $method, array $headers, string $body, mixed $response, mixed $requestHeaders, mixed $requestBody) {
        if ($response === null) {
            return null;
        }
        $errno = $this->safe_integer($response, 'errno');
        if (($errno !== null) && ($errno !== 0)) {
            $errmsg = $this->safe_string($response, 'errmsg', '');
            $feedback = $this->id . ' ' . $body;
            $this->throw_exactly_matched_exception($this->exceptions['exact'], $this->number_to_string($errno), $feedback);
            $this->throw_broadly_matched_exception($this->exceptions['broad'], $errmsg, $feedback);
            throw new ExchangeError($feedback);
        }
        return null;
    }

    public function sign(mixed $path, mixed $api = 'opinion', $method = 'GET', $params = array(), mixed $headers = null, mixed $body = null) {
        /**
         * @ignore
         * builds the request $url and attaches the apikey/EIP-712 authentication $headers for private endpoints
         * @param {string} $path the endpoint $path
         * @param {string|string[]} $api the $api group and $access level
         * @param {string} $method the http $method
         * @param {array} $params the request parameters
         * @param {array} [$headers] request $headers
         * @param {string} [$body] the request $body
         * @return {array} a dict with $url, $method, $body and $headers
         */
        $apiGroup = gettype($api) === 'string' ? $api : $api[0];
        $access = gettype($api) === 'string' ? 'public' : $api[1];
        $baseUrls = $this->urls['api'];
        $baseUrl = $this->safe_string($baseUrls, $apiGroup, $baseUrls['opinion']);
        $url = $baseUrl . '/' . $this->implode_params($path, $params);
        $query = $this->omit($params, $this->extract_params($path));
        $existingHeaders = ($headers !== null) ? $headers : array();
        $headers = $this->extend(array(
            'Accept' => 'application/json',
            'Content-Type' => 'application/json',
        ), $existingHeaders);
        if ($access === 'private') {
            if ($path === 'auth/api-key') {
                // wallet-signature scheme => no $apiKey involved, the signature itself is the credential
                if (($this->walletAddress === null) || ($this->privateKey === null)) {
                    throw new ArgumentsRequired($this->id . ' ' . $path . ' requires a walletAddress and privateKey');
                }
                $actionByMethod = array( 'POST' => 'create', 'GET' => 'get', 'DELETE' => 'delete' );
                $action = $this->safe_string($actionByMethod, $method, 'get');
                $timestamp = $this->number_to_string($this->seconds());
                $headers['OPINION_ADDRESS'] = $this->walletAddress;
                $headers['OPINION_SIGNATURE'] = $this->sign_api_key_auth($this->walletAddress, $action, $timestamp);
                $headers['OPINION_TIMESTAMP'] = $timestamp;
            } else {
                // an empty $this->apiKey counts - deleteApiKey clears it to '' (the
                // strict base types the credential, null can not be assigned)
                $hasDirectApiKey = !$this->is_empty_string($this->apiKey);
                $apiKey = ($hasDirectApiKey) ? $this->apiKey : $this->safe_string($this->options, 'apiKey');
                if ($apiKey === null) {
                    throw new AuthenticationError($this->id . ' ' . $path . ' requires an $apiKey - set it directly or call createApiKey()/fetchApiKey() first');
                }
                $headers['apikey'] = $apiKey;
            }
        }
        if ($method === 'GET') {
            if ($query) {
                $url .= '?' . $this->urlencode($query);
            }
        } else {
            $body = $this->json($query);
        }
        return array( 'url' => $url, 'method' => $method, 'body' => $body, 'headers' => $headers );
    }
}
